// Junta las tres respuestas del RPC y las pasa de hexadecimal a números que se leen.
// Cada nodo anterior se lee por su nombre, por ejemplo $('Pedir el chainId').first().json

function resultado(nodo) {
  const r = $(nodo).first().json;
  if (r.error || r.result === undefined || r.result === null) {
    throw new Error(`«${nodo}» no trajo un resultado: ${JSON.stringify(r.error ?? r)}`);
  }
  return r.result;
}

// Pasa un entero en wei a otra unidad, como texto y sin redondear.
// decimales = 9 para nAVAX (también llamado gwei) y 18 para AVAX.
function enUnidad(wei, decimales) {
  const base = 10n ** BigInt(decimales);
  const entero = wei / base;
  const resto = (wei % base).toString().padStart(decimales, '0').replace(/0+$/, '');
  return resto ? `${entero}.${resto}` : `${entero}`;
}

const chainIdHex = resultado('Pedir el chainId');
const bloque = resultado('Pedir el último bloque');
const precioGas = BigInt(resultado('Pedir el precio del gas'));

const chainId = Number(BigInt(chainIdHex)); // 0xa869 → 43113
const numero = Number(BigInt(bloque.number));
const segundos = Number(BigInt(bloque.timestamp)); // hora Unix: segundos desde 1970
const hora = DateTime.fromSeconds(segundos, { zone: 'America/La_Paz' });
const tarifaBase = BigInt(bloque.baseFeePerGas ?? '0x0');
const GAS_TRANSFERENCIA = 21000n; // lo que gasta mandar AVAX de una wallet a otra, sin contrato

return [
  {
    json: {
      red: chainId === 43113 ? 'Avalanche Fuji C-Chain' : `otra red (chainId ${chainId})`,
      esFuji: chainId === 43113,
      chainId,
      chainIdHex,
      ultimoBloque: numero,
      ultimoBloqueHex: bloque.number,
      horaDelBloque: hora.toFormat('dd/MM/yyyy HH:mm:ss'),
      zonaHoraria: 'America/La_Paz',
      haceSegundos: Math.max(0, Math.round($now.toSeconds() - segundos)),
      transaccionesEnElBloque: bloque.transactions.length,
      gasUsadoEnElBloque: Number(BigInt(bloque.gasUsed)),
      precioDelGas: { wei: precioGas.toString(), nAVAX: enUnidad(precioGas, 9) },
      tarifaBaseDelBloque: { wei: tarifaBase.toString(), nAVAX: enUnidad(tarifaBase, 9) },
      costoDeUnaTransferencia: { gas: Number(GAS_TRANSFERENCIA), AVAX: enUnidad(GAS_TRANSFERENCIA * precioGas, 18) },
      explorador: `https://build.avax.network/explorer/fuji/c-chain/block/${numero}`,
    },
  },
];
